import { spawnSync } from 'node:child_process';
const EXE = '/workspace/dataset/test5_executable';
const t = (label, a, b) => {
  const r = spawnSync(EXE, ['--a', a, '--b', b], { encoding: 'utf8' });
  const cps = [...a].map((c) => c.codePointAt(0).toString(16)).join(',');
  console.log(
    label.padEnd(34),
    b.padEnd(20),
    '=>',
    r.status === 0 ? 'out=' + JSON.stringify(r.stdout) : 'EXIT ' + r.status,
    '| cps:',
    cps,
  );
};
// raw control characters inside the JSON string, one code unit at a time
for (const cc of [0x00, 0x01, 0x07, 0x08, 0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x0e, 0x1f, 0x20, 0x7f, 0x85, 0xa0]) {
  const s = '"a' + String.fromCharCode(cc) + 'b"';
  t('raw U+' + cc.toString(16).padStart(4, '0') + ' maxLength2', s, '{"maxLength":2}');
}
// decomposed vs precomposed e-acute
t('raw e+U+0301 max1', '"é"', '{"maxLength":1}');
t('raw e+U+0301 max2', '"é"', '{"maxLength":2}');
t('raw e+U+0301 min3', '"é"', '{"minLength":3}');
t('raw U+00E9 max1', '"é"', '{"maxLength":1}');
