import { readFileSync, writeFileSync } from 'node:fs';
const p = '/workspace/probe/cases/string-keywords-unicode.json';
const cases = JSON.parse(readFileSync(p, 'utf8'));
const C = String.fromCodePoint;
// note-prefix -> exact instance-arg string, built programmatically so nothing gets normalized
const fixes = {
  // decomposed e + COMBINING ACUTE (U+0301) -- must NOT be NFC-composed
  E1: '"e' + C(0x301) + '"',
  E2: '"e' + C(0x301) + '"',
  E3: '"e' + C(0x301) + '"',
  E5: '"' + C(0xe9) + '"',
  E6: '"' + C(0xe9) + '"',
  E17: '"' + C(0xfeff) + 'a"',
  E18: '"' + C(0xfeff) + 'a"',
  // composite: a + U+1F600 + e + U+0301 + U+1F1FA + U+1F1F8  = 6 code points, 10 UTF-16 units
  D23: '"a' + C(0x1f600) + 'e' + C(0x301) + C(0x1f1fa) + C(0x1f1f8) + '"',
  D24: '"a' + C(0x1f600) + 'e' + C(0x301) + C(0x1f1fa) + C(0x1f1f8) + '"',
  D25: '"a' + C(0x1f600) + 'e' + C(0x301) + C(0x1f1fa) + C(0x1f1f8) + '"',
  // raw control / high chars inside the JSON string
  G13: '"a' + C(0x7f) + 'b"',
  G14: '"a' + C(0x85) + 'b"',
  G15: '"a' + C(0xa0) + 'b"',
  G16: '"a' + C(0x2028) + 'b"',
  G17: '"a' + C(0x01) + 'b"',
  G18: '"a' + C(0x09) + 'b"',
  G19: '"a' + C(0x0a) + 'b"',
  G20: '"a' + C(0x1f) + 'b"',
  // lone surrogate raw in argv
  F13: '"' + '\ud800' + '"',
};
let n = 0;
for (const c of cases) {
  const key = (c.note || '').split(' ')[0];
  if (key in fixes) {
    c.a = fixes[key];
    n++;
  }
}
writeFileSync(p, JSON.stringify(cases, null, 1) + '\n');
console.log('patched', n, 'of', cases.length);
for (const c of cases) {
  const key = (c.note || '').split(' ')[0];
  if (key in fixes)
    console.log(
      key.padEnd(4),
      [...c.a].map((ch) => ch.codePointAt(0).toString(16)).join(','),
      '| cp len of inner string =',
      [...c.a].length - 2,
    );
}
